ck",function(e){if(!osStarted||e.target.closest(".labsos-window")||document.querySelector(".labsos-window.show"))return;capturePointer()});document.addEventListener("keydown",function(e){if(e.code==="ControlRight"){rightCtrlDown=true;if(e.altKey||altGrDown){e.preventDefault();e.stopPropagation();releasePointer();setTimeout(function(){LabsOS.openAdvanced()},0);return}e.preventDefault();releasePointer();return}if(e.code==="AltRight"){altGrDown=true;if(rightCtrlDown||e.ctrlKey){e.preventDefault();e.stopPropagation();releasePointer();setTimeout(function(){LabsOS.openAdvanced()},0);return}}if(e.code==="AltLeft"&&e.ctrlKey){e.preventDefault();e.stopPropagation()}if(!e.ctrlKey||e.altKey||e.metaKey)return;if(e.key==="+"||e.key==="="){e.preventDefault();e.stopPropagation();setBootZoom(bootZoom+ZOOM_STEP)}else if(e.key==="-"||e.key==="_"){e.preventDefault();e.stopPropagation();setBootZoom(bootZoom-ZOOM_STEP)}else if(e.key==="0"){e.preventDefault();e.stopPropagation();setBootZoom(1)}},true);document.addEventListener("keyup",function(e){if(e.code==="ControlRight")rightCtrlDown=false;if(e.code==="AltRight")altGrDown=false});document.addEventListener("wheel",function(e){if(e.ctrlKey){e.preventDefault();setBootZoom(bootZoom+(e.deltaY<0?ZOOM_STEP:-ZOOM_STEP))}},{passive:false});document.addEventListener("contextmenu",function(e){e.preventDefault()});window.addEventListener("resize",function(){checkSize();repositionBoot()});new ResizeObserver(function(){repositionBoot()}).observe(bootContainer);checkSize();repositionBoot();updateFullscreenButton()})();</script></body></html>